mapper.update:
UPDATE CUSTOMER_TB SET
name = #{name},
email = #{email},
phone = #{phone}
WHERE id = #{id}

UPDATE ORDER_STATUS_TB
SET ORDER_STATUS = #{orderStatus}
WHERE ORDER_ID = #{orderId}

mapper.select:
SELECT COUNT(*)
FROM ORDER_TB O
JOIN ORDER_STATUS_TB S ON S.ORDER_ID = O.ID
WHERE O.IDENTIFIER_ID = #{customerId}
AND S.ORDER_STATUS = #{orderStatus}

SELECT COUNT(*)
FROM ORDER_TB O
JOIN DELIVERY_TB D ON D.ORDER_ID = O.ID
WHERE O.IDENTIFIER_ID = #{customerId}
AND D.DELIVERY_STATUS = #{deliveryStatus}
